/// <summary>
/// CB434_BasePriceVersion4StandardCosting, pass custom fields
/// </summary>
[ExtensionOf(classStr(GUPItemBasePriceUpdateValidJob))]
internal final class METGUPItemBasePriceUpdateValidJob_Extension
{
}

Method.Source:
/// <summary>
/// init custom fields
/// </summary>
/// <param name = "_selectionObject"></param>
protected void addBasePriceExtendedFields(SysDaSelection _selectionObject)
{
    next addBasePriceExtendedFields(_selectionObject);
    _selectionObject
        .add(fieldStr(GUPItemBasePrice, METVendClaimEnabled));
}

/// <summary>
/// CB434, after GUPItemBasePrice records are inserted, create standard costing entries
/// for all BasePriceInventoryCost records with no ToDate in this operation batch.
/// </summary>
/// <param name = "_operationGuid">Guid identifying the GUPItemBasePrice records inserted in this run</param>
public void postUpdateValidBasePrice(SysGuid _operationGuid)
{
    next postUpdateValidBasePrice(_operationGuid);

    METProcMetrics procMetrics = METProcMetrics::construct(METBatchLogOperation::BasePriceActivation_ActivateCurrentPrice);
    procMetrics.setSessionGuid(this.parmSessionGuid());
    procMetrics.beginTrace(GUPItemBasePriceUpdateValidJob::description());

    using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
    {
        GUPParameters gupParameters = GUPParameters::find();

        if (gupParameters.METCreateItemPrice)
        {
            GUPItemBasePrice itemBasePrice;
            Set              processedItemDimSet = new Set(Types::String);
            str              itemDimKey;

            while select forUpdate itemBasePrice
                order by itemBasePrice.ItemId, itemBasePrice.InventDimId, itemBasePrice.FromDate desc, itemBasePrice.RecId desc
                where itemBasePrice.OperationGuid                   == _operationGuid
                    && itemBasePrice.PriceType                      == GUPBasePriceType::BasePriceInventoryCost
                    && itemBasePrice.FromDate                       <= METGlobal::systemDateGet()
                    && itemBasePrice.METItemPriceActivationStatus   == METItemPriceActivationStatus::None
                    && (itemBasePrice.ToDate                        == dateNull() || itemBasePrice.ToDate >= METGlobal::systemDateGet())
            {
                itemDimKey = strFmt('%1|%2', itemBasePrice.ItemId, itemBasePrice.InventDimId);

                if (procMetrics)
                {
                    procMetrics.incProcessedCountWithDocument(itemDimKey);
                }

                if (processedItemDimSet.in(itemDimKey))
                {
                    itemBasePrice.metUpdateActivationStatus(METItemPriceActivationStatus::Skipped);
                }
                else
                {
                    itemBasePrice.inventItemPriceCreation();
                }

                if (!processedItemDimSet.in(itemDimKey))
                {
                    processedItemDimSet.add(itemDimKey);
                }
            }
        }

        procMetrics.endTrace();
    }
}
